import{_ as t,o,c as a,ae as r}from"./chunks/framework.Dh1jimFm.js";const d=JSON.parse('{"title":"TM Search (Concordance)","description":"","frontmatter":{},"headers":[],"relativePath":"superlookup/tm-search.md","filePath":"superlookup/tm-search.md"}'),s={name:"superlookup/tm-search.md"};function n(i,e,l,c,h,u){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="tm-search-concordance" tabindex="-1">TM Search (Concordance) <a class="header-anchor" href="#tm-search-concordance" aria-label="Permalink to &quot;TM Search (Concordance)&quot;">​</a></h1><p>Superlookup’s <strong>TMs</strong> tab lets you do fast concordance searches in your Translation Memories (&quot;find where I translated this before&quot;).</p><h2 id="open-it" tabindex="-1">Open it <a class="header-anchor" href="#open-it" aria-label="Permalink to &quot;Open it&quot;">​</a></h2><ul><li><strong>In Supervertaler:</strong> press <code>Ctrl+K</code> (opens Superlookup with the current selection, if any).</li><li><strong>From anywhere (Windows):</strong> press <code>Ctrl+Alt+L</code> (requires AutoHotkey for true global hotkey support).</li></ul><h2 id="how-to-search" tabindex="-1">How to search <a class="header-anchor" href="#how-to-search" aria-label="Permalink to &quot;How to search&quot;">​</a></h2><ol><li>Type (or paste) text into the search box.</li><li>Press <code>Enter</code> (or click <strong>Search</strong>).</li><li>Optional filters: <ul><li><strong>Direction:</strong> Both / Source / Target</li><li><strong>From / To:</strong> language pair filter (leave as <strong>Any</strong> to use all languages)</li></ul></li></ol><h2 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h2><p>At the top of the tab you can switch between:</p><ul><li><strong>Horizontal (Table):</strong> match % + Source/Target side-by-side.</li><li><strong>Vertical (List):</strong> stacked Source/Target entries (classic concordance layout).</li></ul><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><ul><li><strong>Double-click</strong> a result to copy the target text.</li><li><strong>Copy Target</strong> copies the selected target.</li><li><strong>Insert Target</strong> copies the target and prompts you to paste with <code>Ctrl+V</code> in your active application.</li></ul><h2 id="tm-selection" tabindex="-1">TM selection <a class="header-anchor" href="#tm-selection" aria-label="Permalink to &quot;TM selection&quot;">​</a></h2><p>In <strong>Superlookup → Settings → Translation Memories</strong>, you can choose which TMs to search.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you don’t select any TMs in the Superlookup Settings tab, Superlookup searches <strong>all available</strong> TMs.</p></div>',14)]))}const g=t(s,[["render",n]]);export{d as __pageData,g as default};
